function readCodePoint(text, index) {
  const first = text.charCodeAt(index);

  if (first >= 0xd800 && first <= 0xdbff && index + 1 < text.length) {
    const second = text.charCodeAt(index + 1);

    if (second >= 0xdc00 && second <= 0xdfff) {
      return {
        value: ((first - 0xd800) << 10) + (second - 0xdc00) + 0x10000,
        width: 2,
      };
    }
  }

  return { value: first, width: 1 };
}

// Python sorts Unicode strings by code point; JS default sort uses UTF-16 code units.
export function compareUnicodeCodePoints(left, right) {
  if (left === right) {
    return 0;
  }

  let leftIndex = 0;
  let rightIndex = 0;

  while (leftIndex < left.length && rightIndex < right.length) {
    const leftPoint = readCodePoint(left, leftIndex);
    const rightPoint = readCodePoint(right, rightIndex);

    if (leftPoint.value !== rightPoint.value) {
      return leftPoint.value < rightPoint.value ? -1 : 1;
    }

    leftIndex += leftPoint.width;
    rightIndex += rightPoint.width;
  }

  if (leftIndex === left.length && rightIndex === right.length) {
    return 0;
  }

  return leftIndex === left.length ? -1 : 1;
}

export function sortStringsLikePython(values) {
  return [...values].sort(compareUnicodeCodePoints);
}

